# Try to import lxml, fallback to standard library if not available
try:
    from lxml.html import fromstring
    HAVE_LXML = True
except ImportError:
    HAVE_LXML = False
    from html.parser import HTMLParser
    from xml.etree.ElementTree import fromstring as etree_fromstring
    from html import unescape

RE_STRIP_XML_DECLARATION = re.compile(r"^<\?xml [^>]+?\?>")


def _get_html_tree(html_content: str) -> Optional[Any]:
    """Obtain the HTML parse tree for the given HTML content.

    Args:
        html_content: The content to parse.

    Returns:
        The corresponding HTML parse tree.
    """
    html_content = html_content.strip()
    if not html_content:
        return None

    # strip XML declaration, if necessary
    if html_content.startswith("<?xml "):
        html_content = RE_STRIP_XML_DECLARATION.sub("", html_content, count=1)

    if HAVE_LXML:
        try:
            return fromstring(html_content)
        except Exception:
            return None
    else:
        # Fallback implementation using standard library
        try:
            # Try to parse as HTML first
            try:
                return etree_fromstring(f"<div>{html_content}</div>")
            except Exception:
                return etree_fromstring(f"<div><pre>{html_content}</pre></div>")
        except Exception:
            # Fallback: wrap in pre tag
            try:
                return etree_fromstring(f"<div><pre>{html_content}</pre></div>")
            except Exception:
                return None"}

